import 'package:flutter/material.dart';import '../foundation/scene.dart';import '../foundation/spatial_panel.dart';import '../bloom/bloom_scene.dart';import '../quarters/quarter_registry.dart';import '../network/network_territory.dart';import '../chat/character_chat_page.dart';class CivilizationPage extends StatelessWidget{const CivilizationPage({super.key});@override Widget build(BuildContext c)=>Scene(eyebrow:'GATE 1 · CRITERIVOX WORKERS / BLOOM',title:'Bloom',subtitle:'Spatial nexus for navigation, observability and cross-home interaction.',children:[const BloomScene(),SpatialPanel(title:'QUARTERS',child:Wrap(spacing:8,runSpacing:8,children:QuarterRegistry.all.map((q)=>ActionChip(label:Text(q.title),onPressed:()=>Navigator.of(c).push(MaterialPageRoute(builder:(_)=>q.page)))).toList())),const SpatialPanel(title:'NETWORK TERRITORY',child:NetworkTerritory()),SpatialPanel(title:'CHARACTER CHAT',child:Wrap(spacing:8,runSpacing:8,children:const ['syvax','dharen','sandre','kaelen','anuka','vivren','tarkis','pramon','bodhex','medrus','epistre','veridat','manis','viveda','anukor'].map((id)=>_ChatEntry(id)).toList()))]);}

